style.css:
@-moz-document domain("ellipsus.com") {
/* Background and Main Theme Colors */
    body {
        background-color: #ebc0cb !important; /* Soft light pink background */
        color: #4a2c2a !important; /* Dark brown text for contrast */
    }

    /* Header & Navbar */
    header, .navbar, .top-bar {
        background-color: #a67c52 !important; /* Warm brown header */
    }

    /* Buttons */
    button, .btn {
        background-color: #8b5e3c !important; /* Deep brown buttons */
        color: white !important;
        border-radius: 6px !important; /* Softer rounded buttons */
        padding: 6px 12px !important; /* Adjusted padding for better spacing */
        font-size: 14px !important; /* Slightly smaller font size */
    }
    button:hover, .btn:hover {
        background-color: #6d4833 !important; /* Darker brown hover effect */
    }

    /* Text Input & Text Areas */
    input, textarea {
        background-color: #debdc5 !important; /* Light pastel pink input fields */
        color: #4a2c2a !important; 
        border: 1px solid #a67c52 !important;
    }

    /* Links */
    a {
        color: #6d4833 !important; /* Rich brown links */
    }
    a:hover {
        color: #523528 !important; /* Darker brown hover effect */
    }

    /* Sidebar & Panels */
    .sidebar, .panel, .card {
        background-color: #f0d6cb !important; /* Light pink panels */
        border-radius: 10px !important;
        box-shadow: 2px 2px 8px rgba(139, 94, 60, 0.2) !important;
        padding: 10px !important; /* Less clamped spacing */
    }

    /* Layout & Platform Buttons Fix */
    .layout-button, .platform-button {
        font-size: 13px !important;
        padding: 5px 10px !important;
        margin: 5px !important;
        border-radius: 5px !important;
    }
}
